# qx_roman_to_int :: 'III'
def qx_roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    out = 0
    for i, c in enumerate(s):
        if i + 1 < len(s) and vals[c] < vals[s[i+1]]: out -= vals[c]
        else: out += vals[c]
    return out

if __name__ == '__main__':
    print(qx_roman_to_int('III'))

